do local defs=UnitDefs or{}local merge=table.merge local function addCat(existing,category)if type(existing)~='string'or existing==''then return category end for token in string.gmatch(existing,'%S+')do if token==category then return existing end end return existing..' '..category end local function getScale(mo)local resourceIncome=tonumber(mo.multiplier_resourceincome)or 1 local buildPower=tonumber(mo.multiplier_buildpower)or 1 local buildRange=tonumber(mo.multiplier_builddistance)or 1.7 local waveMultiplier=tonumber(mo.raptor_spawncountmult)or 3 local firstWaveBoost=tonumber(mo.raptor_firstwavesboost)or 4 local economyPressure=(resourceIncome*0.5)+(buildPower*0.2)+((buildRange/1.7)*0.3)local wavePressure=((3/math.max(waveMultiplier,0.1))*0.6)+((4/math.max(firstWaveBoost,0.1))*0.4)return math.max(1,1.45*economyPressure*wavePressure)end local function resolveMul(ss,divider)return math.max(1,1+(((ss or 1.7)-1)/divider))end local function vtolOnly(weapon)if type(weapon)~='table'or type(weapon.onlytargetcategory)~='string'then return false end local hasVtol=false for token in string.gmatch(weapon.onlytargetcategory,'%S+')do if token=='VTOL'then hasVtol=true elseif token~='GROUNDSCOUT'then return false end end return hasVtol end local function avoidObj(unitDef)if type(unitDef)~='table'then return end unitDef.nochasecategory=addCat(unitDef.nochasecategory,'SATS')for _,weapon in pairs(unitDef.weapons or{})do if type(weapon)=='table'and not vtolOnly(weapon)then weapon.badtargetcategory=addCat(weapon.badtargetcategory,'SATS')end end end local function scaled(value,multiplier)return math.max(1,math.floor(value*multiplier+0.5))end local function copy(value)if type(value)~='table'then return value end local out={}for key,item in pairs(value)do out[key]=copy(item)end return out end local function cu(source,target)local base=defs[source] if not base then return nil end if defs[target]then return defs[target]end defs[target]=copy(base)return defs[target] end local function sid(un