mageMultiplier'then weaponDef[key]=value end end unitDef.weapondefs[weaponName]=weaponDef end local spring=Spring local mo=spring and spring.GetModOptions and spring.GetModOptions()or{}local ss=getScale(mo)local hm=resolveMul(ss,1.8)local dm=resolveMul(ss,2.4)local qtm=math.max(1,tonumber(mo.raptor_queentimemult)or 1.3)local angerT={45,72,74,92,94,110}local aFirst,aLast=angerT[1],angerT[#angerT] local aEnd=qtm*aLast/1.3 local aStretch=(aEnd-aFirst)/(aLast-aFirst)for idx=2,#angerT do angerT[idx]=math.floor(aFirst+(angerT[idx]-aFirst)*aStretch)end local pScale=1 if Spring.Utilities.Gametype.IsRaptors()then pScale=(#Spring.GetTeamList()-2)/12 end local scm=tonumber(mo.raptor_spawncountmult)or 3 pScale=pScale*(scm/3)local function pCap(n)return math.max(1,math.ceil(n*pScale))end local function findMelee(unitDef)if not unitDef or not unitDef.weapondefs then return nil end if unitDef.weapondefs.melee then return'melee'end for _,weapon in pairs(unitDef.weapons or{})do local weaponName=weapon and weapon.def if type(weaponName)=='string'and unitDef.weapondefs[weaponName] and(weaponName:match('melee')or weaponName:match('claw|talon|bite|flame'))then return weaponName end end for weaponName in pairs(unitDef.weapondefs)do if type(weaponName)=='string'and(weaponName:match('melee')or weaponName:match('claw|talon|bite|flame'))then return weaponName end end end local function pm(unitDef,damage,reloadtime,colorA,colorB)local weaponName=findMelee(unitDef)if not unitDef or not unitDef.weapondefs or not weaponName then return end local melee=copy(unitDef.weapondefs[weaponName])melee.name='Doomfire Claws'melee.reloadtime=reloadtime or melee.reloadtime melee.firestarter=100 melee.edgeeffectiveness=0.85 melee.explosiongenerator='custom:heatray-large'melee.soundstart='heatray3'melee.soundhitwet='sizzle'melee.rgbcolor=colorA or'1 0.45 0.1'melee.rgbcolor2=colorB or'0.95 0.9 0.35'melee.damage=copy(melee.damage or{})melee.damage.default=damage if melee.damage.commanders then melee.damage.comma