l speedScale=resMul(ss,6)local boosts={{name='raptor_land_swarmer_basic_t1_v1',scale={health=1.18*hm,speed=1.03,damageMultiplier=dm}},{name='raptor_land_swarmer_basic_t2_v1',scale={health=1.16*hm,speed=1.04,damageMultiplier=dm}},{name='raptor_land_assault_basic_t2_v1',scale={health=1.18*hm,speed=1.04,damageMultiplier=dm}},{name='raptor_allterrain_arty_basic_t2_v1',scale={health=1.2*hm,damageMultiplier=dm}},{name='raptor_air_fighter_basic_t2_v1',scale={health=1.14*hm,speed=1.05,damageMultiplier=dm}},{name='raptor_land_swarmer_heal_t2_v1',scale={health=1.32*hm,speed=1.06,autoheal=1.45,damageMultiplier=1.08*dm}},{name='raptor_land_swarmer_emp_t2_v1',scale={health=hm,damageMultiplier=dm}},{name='raptor_allterrain_arty_emp_t2_v1',scale={health=hm,damageMultiplier=dm}},{name='raptor_land_swarmer_acids_t2_v1',scale={health=hm,speed=1.02,damageMultiplier=dm}},{name='raptor_allterrain_arty_acid_t2_v1',scale={health=hm,damageMultiplier=dm}},{name='raptor_land_swarmer_fire_t2_v1',scale={health=hm,speed=1.03,damageMultiplier=dm}},{name='raptor_land_assault_basic_t4_v1',scale={health=hm,speed=1.03,damageMultiplier=dm}},{name='raptor_land_swarmer_heal_t3_v1',scale={health=1.5*hm,speed=1.08,autoheal=1.7,damageMultiplier=1.15*dm}},{name='raptor_land_swarmer_heal_t4_v1',scale={health=1.8*hm,speed=1.1,autoheal=1.9,damageMultiplier=1.2*dm}},{name='raptor_land_swarmer_brood_t4_v1',scale={health=1.6*hm,speed=1.08,autoheal=1.25,damageMultiplier=1.18*dm}},{name='raptor_air_bomber_basic_t2_v1',scale={health=hm,damageMultiplier=dm}},{name='raptor_matriarch_fire',scale={health=hm,damageMultiplier=dm}},{name='raptor_matriarch_basic',scale={health=hm,damageMultiplier=dm}},{name='raptor_matriarch_acid',scale={health=hm,damageMultiplier=dm}},{name='raptor_matriarch_electric',scale={health=hm,damageMultiplier=dm}},{name='critter_penguinking',scale={health=1.18*hm,speed=1.05,damageMultiplier=1.15*dm}},{name='armscavengerbossv2_hard',scale={health=1.28*hm,speed=1.04,damageMultiplier=1.12*dm}},{name='scavengerbossv4_normal',scale={health=1.35*hm,speed=1.05,damageMultiplier=1.18*dm}},}local function cap(name,limit)local unitDef=defs[name] if unitDef then defs[name]=merge(unitDef,{maxthisunit=limit})end end local function clampWeaponRanges(name,maxRange)local unitDef=defs[name] if not unitDef or type(unitDef.weapondefs)~='table'then return end local patchedWeaponDefs={}local hasPatch=false for weaponName,weaponDef in pairs(unitDef.weapondefs)do if type(weaponDef)=='table'and type(weaponDef.range)=='number'and weaponDef.range>maxRange then patchedWeaponDefs[weaponName]=merge(weaponDef,{range=maxRange})hasPatch=true end end if hasPatch then unitDef.weapondefs=merge(unitDef.weapondefs,patchedWeaponDefs)defs[name]=unitDef end end local function setWeaponRange(name,weaponName,maxRange)local unitDef=defs[name] if not unitDef or type(unitDef.weapondefs)~='table'or type(unitDef.weapondefs[weaponName])~='table'then return end unitDef.weapondefs[weaponName]=merge(unitDef.weapondefs[weaponName],{range=maxRange})defs[name]=unitDef end for _,entry in ipairs(boosts)do boost(entry.name,entry.scale)end for name,_ in pairs(defs)do if string.find(name,'^raptor_')or name=='critter_penguinking'or string.find(name,'scavengerboss')then local unitDef=defs[name] if unitDef then local customparams=unitDef.customparams or{}if not customparams.doom_scaled_hp_mul or not customparams.doom_scaled_dmg_mul or not customparams.doom_scaled_speed_mul then boost(name,{health=customparams.doom_scaled_hp_mul and nil or hm,speed=customparams.doom_scaled_speed_mul and nil or speedScale,damageMultiplier=customparams.doom_scaled_dmg_mul and nil or dm,})end avoidObj(unitDef)end end end local mo=Spring and Spring.GetModOptions and Spring.GetModOptions()or{}local qCount=tonumber(mo.raptor_queen_count)or 1 cap('raptor_matriarch_fire',1)cap('raptor_matriarch_basic',1)cap('armscavengerbossv2_hard',math.max(1,qCount))cap('scavengerbossv4_normal',math.max(1,qCount))clampWeaponRanges('armscavengerbossv2_hard',1700)setWeaponRange('scavengerbossv4_normal','shoulderturrets',1800)setWeaponRange('scavengerbossv4_normal','turbo_shoulderturrets',1800)setWeaponRange('scavengerbossv4_normal','special_botcannon',1800)if defs['armscavengerbossv2_hard']then avoidObj(defs['armscavengerbossv2_hard'])end if defs['scavengerbossv4_normal']then avoidObj(defs['scavengerbossv4_normal'])end end

