do local defs=UnitDefs or{}local merge=table.merge local function squad(minAnger,maxAnger,behavior,amount,rarity,weight,distance,chance)return{raptorcustomsquad=true,raptorsquadunitsamount=amount or 1,raptorsquadminanger=minAnger,raptorsquadmaxanger=maxAnger,raptorsquadweight=weight or 1,raptorsquadrarity=rarity or'basic',raptorsquadbehavior=behavior or'berserk',raptorsquadbehaviordistance=distance or 500,raptorsquadbehaviorchance=chance or 0.75,}end local function assignSquad(name,params,label,tooltip)local unitDef=defs[name] if not unitDef then return end local custom=merge(unitDef.customparams or{},params)if label then custom.i18n_en_humanname=label end if tooltip then custom.i18n_en_tooltip=tooltip end unitDef.customparams=custom end assignSquad('raptor_land_assault_basic_t2_v1',squad(0,18,'berserk',6,'basic',7,500,0.82))assignSquad('raptor_land_swarmer_basic_t2_v1',squad(4,18,'raider',14,'basic',9,500,0.8))assignSquad('raptor_land_swarmer_emp_t2_v1',squad(12,26,'raider',10,'basic',8,500,0.78),'Shock Swarmer','Fast control packs that signal Doom Mode is ramping.')assignSquad('raptor_allterrain_arty_emp_t2_v1',squad(20,38,'artillery',4,'special',4,1600,0.72),'Shock Mortar','EMP siege support for shock-themed waves.')assignSquad('raptor_land_swarmer_acids_t2_v1',squad(10,24,'raider',12,'basic',8,500,0.8),'Blight Swarmer','Corrosive flankers that make acid bloom waves feel unfair in the right way.')assignSquad('raptor_allterrain_arty_acid_t2_v1',squad(22,42,'artillery',4,'special',3,1800,0.72),'Blight Mortar','Acid artillery used in bloom-themed pressure waves.')assignSquad('raptor_land_swarmer_fire_t2_v1',squad(14,30,'berserk',10,'basic',6,500,0.78),'Cinder Swarmer','Pyro rushers for stampede waves.')assignSquad('raptor_land_assault_basic_t4_v1',squad(24,45,'berserk',4,'special',4,550,0.76),'Stampede Brawler','Heavy bruisers that replace raw count with raw panic.')assignSquad('raptor_land_swarmer_heal_t2_v1',squad(72,1000,'raider',8,'basic',4,550,0.76),'Brood Healer','Support wave that sticks around long enough to matter when mini queens hit.')assignSquad('raptor_land_swarmer_heal_t3_v1',squad(72,1000,'raider',6,'special',4,650,0.82),'Brood Shepherd','Higher-tier support that keeps late Doom escorts alive through sustained pressure.')assignSquad('raptor_land_swarmer_heal_t4_v1',squad(72,1000,'raider',4,'special',4,700,0.8),'Apex Brood Healer','Late-wave healer escort that keeps boss packs harder to clear when available.')assignSquad('raptor_land_swarmer_brood_t4_v1',squad(36,130,'raider',10,'special',5,600,0.86),'Brood Stampede','Hatchling avalanche that keeps Doom bosses buried in backup from mini queens onward.')assignSquad('raptor_air_fighter_basic_t2_v1',squad(12,26,'raider',7,'basic',5,700,0.72),'Shrieker Flight','Air cover that keeps anti-swarm defenses honest.')assignSquad('raptor_air_bomber_basic_t2_v1',squad(24,45,'artillery',4,'special',3,1200,0.7),'Ruin Bombardiers','Themed bombing run that punishes static greed.')assignSquad('raptor_matriarch_fire',squad(56,110,'berserk',1,'special',2,650,0.58),'Pyro Matron','Rare theme boss for cinder stampedes.')assignSquad('raptor_matriarch_basic',squad(60,115,'berserk',1,'special',2,650,0.58),'Matron of Ruin','Late-wave centerpiece that adds weight without adding clutter.')local function weakenBoss(name)local u=defs[name] if not u then return end if u.health then u.health=u.health*0.33 end if u.weapondefs then local newWeapons={}for wk,w in pairs(u.weapondefs)do local nw=merge({},w)if nw.damage then nw.damage=merge({},nw.damage)for k,v in pairs(nw.damage)do if type(v)=='number'then nw.damage[k]=math.max(1,v*0.33)end end end newWeapons[wk]=nw end u.weapondefs=newWeapons end end weakenBoss('armscavengerbossv2_hard')weakenBoss('scavengerbossv4_normal')local mo=Spring and Spring.GetModOptions and Spring.GetModOptions()or{}local qCount=tonumber(mo.raptor_queen_count)or 1 assignSquad('armscavengerbossv2_hard',squad(80,130,'berserk',math.max(3,qCount),'special',3,1700,0.6),'Scav Harbinger','Frequent siege escort that starts backing up mini queens instead of waiting for the final boss window.')assignSquad('scavengerbossv4_normal',squad(90,130,'berserk',math.max(3,qCount),'special',3,950,0.56),'Scav Nightmare Core','Heavy scav escort that overlaps late mini queens, Doom Queen, and Ascendant events.')end

